const r=await tools.exec_command({cmd:"cat > /tmp/weather_partial.py <<'PY'
import pandas as pd,numpy as np
from scipy.spatial.distance import cdist
S=pd.read_csv('/app/dataset/stations.csv').set_index('station_id');R=pd.read_csv('/app/dataset/readings.csv');W=pd.read_csv('/app/dataset/weather_stations.csv').set_index('weather_station_id'); WR=pd.read_csv('/app/dataset/weather_readings.csv');pol=R.groupby('station_id').pollutant.first();times=sorted(R.timestamp.unique());Y=R.pivot(index='timestamp',columns='station_id',values='current_reading').reindex(times);Yi=Y.interpolate(limit_direction='both')
C=S[['latitude','longitude']].to_numpy().copy();C[:,1]*=.63;WC=W[['latitude','longitude']].to_numpy().copy();WC[:,1]*=.63;D=pd.DataFrame(cdist(C,C)*111,index=S.index,columns=S.index);WD=pd.DataFrame(cdist(C,WC)*111,index=S.index,columns=W.index)
wv=['temperature_c','humidity_pct','wind_speed_m_s','rain_accumulation_mm'];wx={v:WR.pivot(index='timestamp',columns='weather_station_id',values=v).reindex(times) for v in wv}
rows=[]
for st in S.index:
 peers=D.loc[st].drop(st).loc[lambda d: pol[d.index].eq(pol[st])].sort_values()
 if pol[st]=='PM10': peers=peers.drop('ST040',errors='ignore')
 nn=peers.index[:8]; weights=np.exp(-peers.loc[nn].to_numpy()/3)
 ref=np.average((Yi[nn]-Yi[nn].mean()).to_numpy(),axis=1,weights=weights)
 yy=Y[st].to_numpy();m=~np.isnan(yy);obs=yy[m];ref=ref[m];ws=WD.loc[st].idxmin()
 for v in wv:
  for scope,w in [('local',wx[v][ws].to_numpy()[m]),('city',wx[v].median(axis=1).to_numpy()[m]),('local_dev',(wx[v][ws]-wx[v].median(axis=1)).to_numpy()[m])]:
   for trend in [False,True]:
    X=np.stack([np.ones(len(obs)),ref],axis=1)
    if trend:X=np.column_stack([X,np.arange(len(yy))[m]])
    res=obs-X@np.linalg.lstsq(X,obs,rcond=None)[0]
    wres=w-X@np.linalg.lstsq(X,w,rcond=None)[0]
    corr=np.corrcoef(res,wres)[0,1]
    beta=np.dot(res,wres)/np.dot(wres,wres)
    rows.append([st,pol[st],len(obs),v,scope,trend,corr,beta,ws])
f=pd.DataFrame(rows,columns=['st','pol','n','var','scope','trend','r','beta','ws'])
for trend in [False,True]:
 for scope in ['local','city','local_dev']:
  print('\nTrend',trend,'scope',scope)
  print(f.query('trend==@trend and scope==@scope').assign(absr=lambda d:d.r.abs()).sort_values('absr',ascending=False).head(20).round(3).to_string(index=False))
f.to_csv('/tmp/weather_partial.csv',index=False)
